mapper.select:
select p.*,
  (select count(*) from visible_backup_record b where b.database_id = p.id) backup_count,
  (select max(b.event_time) from visible_backup_record b where b.database_id = p.id) latest_event
from (
  select d.* from visible_database_catalog d

  order by d.name, d.id
  limit #{limit} offset #{offset}
) p
order by p.name, p.id

select d.*, coalesce(s.backup_count, 0) backup_count, s.latest_event
from visible_database_catalog d
left join (
  select database_id, count(*) backup_count, max(event_time) latest_event
  from visible_backup_record
  where database_id = #{id}
  group by database_id
) s on s.database_id = d.id
where d.id = #{id}

mapper.update:
update database_catalog
set monitor_from = #{firstDate}
where name = #{name} and monitor_from_auto = true and monitor_from > #{firstDate}
